import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {mkdtemp,readFile,writeFile,mkdir,rm} from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const label=process.argv[2]||'cenas',out='/tmp/legendgirl-yuna-'+label;
await mkdir(out,{recursive:true});await mkdir('docs/diario-ia/qa-resultados/yuna',{recursive:true});
const profile=await mkdtemp(path.join(os.tmpdir(),'legendgirl-yuna-chrome-'));
const chrome=spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',['--headless=new','--mute-audio','--no-first-run','--no-default-browser-check','--autoplay-policy=no-user-gesture-required','--remote-debugging-port=0','--user-data-dir='+profile,'about:blank'],{stdio:'ignore'});
let ws;
try{
 let port;for(let i=0;i<100;i++){try{port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break;}catch{}await new Promise(r=>setTimeout(r,100));}
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await(await fetch('http://127.0.0.1:'+port+'/json/list')).json();ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};
 await call('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});
 await call('Page.navigate',{url:'http://127.0.0.1:3000/docs/diario-ia/qa/yuna/phase.html'});for(let i=0;i<300;i++){if(await evaluate('Boolean(window.phase?.ready)'))break;await new Promise(r=>setTimeout(r,100));}
 await evaluate(`(()=>{if(!phase.ready)throw Error(phase.error||'Jardim indisponível');phase.setPaused(false);window.frames=[];window.special=[];})()`);
 const results=[];
 for(const difficulty of ['NORMAL','EASY']){
  const report=await evaluate(`(async()=>{
   const {createGardenState,retryGarden,restoreGardenState}=await import('/src/js/garden/GardenSimulation.js');
   const {createPilot}=await import('/docs/diario-ia/qa/yuna/piloto-base.mjs');
   phase.difficulty='${difficulty}';phase.state=createGardenState('${difficulty}');let pilot=createPilot(),elapsed=0,retries=0,next=0,drawTotal=0,drawMax=0,draws=0;const visited=new Set(),events={},seen=new Set();
   phase.audio.event=type=>events[type]=(events[type]||0)+1;
   let pad={connected:true,axes:[0],buttons:Array.from({length:16},()=>({pressed:false}))};
   const original=Object.getOwnPropertyDescriptor(navigator,'getGamepads');Object.defineProperty(navigator,'getGamepads',{configurable:true,value:()=>[pad]});
   try{
    for(let tick=0;elapsed<1200&&phase.state.stage!=='COMPLETE';tick++){
     if(phase.reading()&&tick%2===0){window.dispatchEvent(new KeyboardEvent('keydown',{code:'Enter'}));window.dispatchEvent(new KeyboardEvent('keyup',{code:'Enter'}));}const input=pilot(phase.state);pad.axes[0]=input.x;pad.buttons[0].pressed=input.jump;phase.update(1);elapsed+=1/60;
     const start=performance.now();phase.render();const cost=performance.now()-start;drawTotal+=cost;drawMax=Math.max(drawMax,cost);draws++;
     const s=phase.state;for(const bee of s.encounters?.bees??[])if(['prepare','dive','return'].includes(bee.phase)&&!seen.has(bee.phase)&&'${difficulty}'==='NORMAL'){seen.add(bee.phase);special.push({label:'abelha-'+bee.phase,state:structuredClone(s)});}for(const worm of s.encounters?.worms??[])if(worm.exposure>.6&&!seen.has('minhoca')&&'${difficulty}'==='NORMAL'){seen.add('minhoca');special.push({label:'minhoca-saindo',state:structuredClone(s)});}if(s.encounters?.panic&&!seen.has(s.encounters.panic.id)&&'${difficulty}'==='NORMAL'){seen.add(s.encounters.panic.id);special.push({label:s.encounters.panic.id,state:structuredClone(s)});}if(s.encounters?.panic?.id==='besouro-nuvens-finais'&&s.encounters.panic.elapsed>2&&!s.player.onGround&&!seen.has('nuvens-ar')&&'${difficulty}'==='NORMAL'){seen.add('nuvens-ar');special.push({label:'nuvens-perseguicao-no-ar',state:structuredClone(s)});}if(s.player.onGround)visited.add(s.player.support);
     if(s.player.x>=next){if('${difficulty}'==='NORMAL')frames.push(structuredClone(s));next=s.player.x+850;}
     if(s.stage==='GAME_OVER'){if(++retries>8)throw Error('Mais de oito derrotas: x='+s.player.x);retryGarden(s);pilot=createPilot();}
     if(tick%600===0)await new Promise(r=>setTimeout(r,0));
    }
   }finally{if(original)Object.defineProperty(navigator,'getGamepads',original);else delete navigator.getGamepads;}
   const s=phase.state;if(s.stage!=='COMPLETE')throw Error('Percurso não terminou: '+JSON.stringify({x:s.player.x,stage:s.stage,panic:s.panic,player:s.player,input:phase.input.sample(),paused:phase.paused}));
   const restored=restoreGardenState(phase.snapshot().state,'${difficulty}');if(restored.stage!=='COMPLETE')throw Error('Conclusão não restaurada');
   return{difficulty:'${difficulty}',minutos:elapsed/60,retries,events,visited:[...visited],renders:draws,desenhoMedio:drawTotal/draws,desenhoMaximo:drawMax,besouros:s.encounters?.consumed};
  })()`);results.push(report);console.log(JSON.stringify(report));
 }
 for(const [name,width,height]of [['desktop',1280,800],['retrato',390,844],['paisagem',844,390]]){
  await call('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:name!=='desktop'});
  for(const [stage,age]of [['INTRO',0],['INTRO',6],['INTRO',29],['COMPLETE',1],['COMPLETE',22],['COMPLETE',52]]){
   const data=await evaluate(`(()=>{phase.canvas.width=${width};phase.canvas.height=${height};const old=phase.state.stage,age=phase.state.age;phase.state.stage='${stage}';phase.state.age=${age};phase.state.story.openingDone=false;phase.state.story.endingDone=false;phase.state.story['${stage}'==='INTRO'?'openingIndex':'endingIndex']=Math.min('${stage}'==='INTRO'?8:9,Math.floor(${age}/5));phase.state.story.cardAge=1;phase.render();const image=phase.canvas.toDataURL();phase.state.stage=old;phase.state.age=age;return image;})()`);
   await writeFile(out+'/'+name+'-'+stage+'-'+age+'.png',Buffer.from(data.split(',')[1],'base64'));
  }
 }
 await evaluate('phase.canvas.width=1280;phase.canvas.height=800');
 const specials=await evaluate('special.length');
 for(const [format,w,h]of [['desktop',1280,800],['retrato',390,844],['paisagem',844,390]]){await call('Emulation.setDeviceMetricsOverride',{width:w,height:h,deviceScaleFactor:1,mobile:format!=='desktop'});for(let i=0;i<specials;i++){const data=await evaluate(`(()=>{phase.canvas.width=${w};phase.canvas.height=${h};phase.state=special[${i}].state;phase.render();const before=JSON.stringify(phase.state);phase.render();if(before!==JSON.stringify(phase.state))throw Error('Renderer alterou o domínio');return{label:special[${i}].label,image:phase.canvas.toDataURL()};})()`);await writeFile(out+'/'+format+'-'+data.label+'.png',Buffer.from(data.image.split(',')[1],'base64'));}}await call('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});await evaluate('phase.canvas.width=1280;phase.canvas.height=800');
 const count=await evaluate('frames.length');
 for(let first=0;first<count;first+=24){const data=await evaluate(`(()=>{const canvas=document.createElement('canvas');canvas.width=1536;canvas.height=864;const ctx=canvas.getContext('2d');ctx.fillStyle='#f5efe2';ctx.fillRect(0,0,1536,864);for(let i=${first};i<Math.min(${first+24},frames.length);i++){phase.state=frames[i];phase.render();const x=(i-${first})%6*256,y=Math.floor((i-${first})/6)*216;ctx.drawImage(phase.canvas,x,y,256,160);ctx.fillStyle='#203e28';ctx.font='12px sans-serif';ctx.fillText(i+' x '+Math.round(phase.state.player.x)+' '+phase.state.player.terrain,x+4,y+180);}return canvas.toDataURL();})()`);await writeFile(out+'/percurso-'+first+'.png',Buffer.from(data.split(',')[1],'base64'));}
 await writeFile(out+'/resultado.json',JSON.stringify(results,null,2));await writeFile('docs/diario-ia/qa-resultados/yuna/'+label+'.json',JSON.stringify(results,null,2));
 console.log('Percursos NORMAL/EASY completos; capturas para inspeção crítica: '+out);
}finally{ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
